mapper.select:
SELECT session_id, summary_json, summarized_message_id, version, expires_at, update_time
FROM ai_agent_conversation_session
WHERE session_id = #{sessionId}

mapper.update:
UPDATE ai_agent_conversation_session
SET summary_json = #{session.summaryJson},
    summarized_message_id = #{session.summarizedMessageId},
    version = version + 1,
    expires_at = #{session.expiresAt},
    update_time = #{session.updateTime}
WHERE session_id = #{session.sessionId}
  AND version = #{expectedVersion}
